<section class="dashboard-section"><h2><?= count($projetos) ?> projeto(s) encontrado(s)</h2><?php if(empty($projetos)): ?><div class="projetos-vazio">Nenhum projeto aberto corresponde aos filtros.</div><?php else: ?><div class="lista-simples"><?php foreach($projetos as $p): ?><article class="projeto-card"><div class="projeto-card-topo"><div><h3><?= eExplorar((string)$p['titulo']) ?></h3><p style="margin-top:5px;color:var(--cor-texto-secundario);">Cliente: <?= eExplorar((string)$p['nome_cliente']) ?></p></div><span class="projeto-status"><?= eExplorar($categorias[$p['categoria']]??(string)$p['categoria']) ?></span></div><p style="margin-top:14px;line-height:1.5;"><?= eExplorar((string)$p['descricao_resumida']) ?></p><div class="projeto-meta" style="margin-top:16px;"><span>Orçamento: <strong><?= dinheiroExplorar((float)($p['orcamento_min']??0)) ?> a <?= dinheiroExplorar((float)($p['orcamento_max']??0)) ?></strong></span><span>Propostas: <strong><?= (int)$p['total_propostas'] ?></strong></span></div><div class="acoes-inline"><a class="botao-principal" href="projeto.php?id=<?= (int)$p['id'] ?>">Ver projeto</a><?php if(!empty($p['minha_proposta_id'])): ?><span class="tag">Você já enviou proposta</span><?php endif; ?></div></article><?php endforeach; ?></div><?php endif; ?></section>
